INSERT INTO curriculum_nodes (id, slug, phase_id, order_index, title, subtitle, cs_foundation, ai_convergence, xp_reward, level_required, position_x, position_y, handbook_markdown, starter_code, test_suite, defense_prompts) VALUES
('node-9-6', 'phase-09-lesson-06-tensor-strides-memory-layouts-einstein-su', 'module-4', 6, 'Lesson 4.6: Tensor Strides, Memory Layouts & Einstein Summation (Einsum)', 'Prerequisites: Phase 0, Lesson 9.1', 'Prerequisites: Phase 0, Lesson 9.1 | Subtopics: 6 items', 'Systems project application', 280, 10, 2250.0, 300.0, '# Lesson 9.6: Tensor Strides, Memory Layouts & Einstein Summation (Einsum)

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0, Lesson 9.1
- **Subtopics**:
  - `9.6.1` Tensor storage internals: 1D contiguous memory buffer, shape tuple, and stride tuple
  - `9.6.2` Row-major (C-order) vs Column-major (Fortran-order) layouts: stride calculation formula ($s_i = \prod_{j=i+1}^{d-1} n_j$)
  - `9.6.3` Non-contiguous tensors: slicing, transposing, and broadcasting creating zero-copy views by modifying strides
  - `9.6.4` Broadcasting rules: matching dimensions from right to left, dimension compatibility ($d_1 == d_2$ or $d_1 == 1$ or $d_2 == 1$)
  - `9.6.5` The `.contiguous()` operation: when deep learning frameworks must reallocate memory to re-establish sequential strides
  - `9.6.6` Einstein Summation notation (`einsum`): index notation, implicit vs explicit modes, expressing matmul, batch matmul, transpose, and attention
- **Key Failure Modes & Edge Cases**: Invoking `.view()` on a non-contiguous tensor in PyTorch triggering runtime errors; stride bugs causing silent memory corruptions.
- **Verification & Mastery Check**: Implement a custom `Tensor` data structure in Python managing arbitrary shapes, strides, broadcasting, and slicing views over a 1D list.
- **Project Application**: GradFlow: Core multi-dimensional Tensor and stride engine.', '{"solution.py": "# Phase 9 // Lesson 9.6: Tensor Strides, Memory Layouts & Einstein Summation (Einsum)\n\ndef solve():\n    \"\"\"\n    Verification: Implement a custom `Tensor` data structure in Python managing arbitrary shapes, strides, broadcastin\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.6", "subtopics_count": 6, "verification_criteria": "Implement a custom `Tensor` data structure in Python managing arbitrary shapes, strides, broadcasting, and slicing views over a 1D list.", "subtopics": ["9.6.1 Tensor storage internals: 1D contiguous memory buffer, shape tuple, and stride tuple", "9.6.2 Row-major (C-order) vs Column-major (Fortran-order) layouts: stride calculation formula ($s_i = \\prod_{j=i+1}^{d-1} n_j$)", "9.6.3 Non-contiguous tensors: slicing, transposing, and broadcasting creating zero-copy views by modifying strides", "9.6.4 Broadcasting rules: matching dimensions from right to left, dimension compatibility ($d_1 == d_2$ or $d_1 == 1$ or $d_2 == 1$)", "9.6.5 The `.contiguous()` operation: when deep learning frameworks must reallocate memory to re-establish sequential strides", "9.6.6 Einstein Summation notation (`einsum`): index notation, implicit vs explicit modes, expressing matmul, batch matmul, transpose, and attention"]}'::jsonb, '["Explain how this implementation prevents: Invoking `.view()` on a non-contiguous tensor in PyTorch triggering runtime errors; stride bugs causing silent memory co", "How does Tensor Strides, Memory Layouts & Einstein Summation (Einsum) scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-7', 'phase-09-lesson-07-multivariate-differential-calculus-gradie', 'module-4', 7, 'Lesson 4.7: Multivariate Differential Calculus: Gradients, Jacobians & Directional Derivatives', 'Prerequisites: Phase 2, Lesson 9.1', 'Prerequisites: Phase 2, Lesson 9.1 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 350.0, '# Lesson 9.7: Multivariate Differential Calculus: Gradients, Jacobians & Directional Derivatives

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 2, Lesson 9.1
- **Subtopics**:
  - `9.7.1` Functions $f: \mathbb{R}^n \to \mathbb{R}$: partial derivatives, gradient vector $\nabla f(x)$, and steepness interpretation
  - `9.7.2` Directional derivatives: $D_v f(x) = \nabla f(x)^T v$; gradient as the direction of steepest ascent
  - `9.7.3` Vector-valued functions $f: \mathbb{R}^n \to \mathbb{R}^m$: the Jacobian matrix $J \in \mathbb{R}^{m \times n}$ of all first-order partials
  - `9.7.4` Matrix calculus conventions: numerator layout (Jacobian formulation) vs denominator layout (gradient formulation)
  - `9.7.5` Vector-Jacobian Products (VJP): why reverse-mode automatic differentiation computes $v^T J$ rather than full $J$
  - `9.7.6` Jacobian-Vector Products (JVP): forward-mode automatic differentiation and directional derivative evaluation
- **Key Failure Modes & Edge Cases**: Mixing numerator and denominator layout conventions mid-derivation, yielding transposed matrix gradient dimensions.
- **Verification & Mastery Check**: Derive by hand and verify numerically via finite differences the analytical gradient and Jacobian of vector mapping $f(x) = Ax / \|x\|_2$.
- **Project Application**: GradFlow: Analytical gradient calculation foundations.', '{"solution.py": "# Phase 9 // Lesson 9.7: Multivariate Differential Calculus: Gradients, Jacobians & Directional Derivatives\n\ndef solve():\n    \"\"\"\n    Verification: Derive by hand and verify numerically via finite differences the analytical gradient and Jacobian of\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.7", "subtopics_count": 6, "verification_criteria": "Derive by hand and verify numerically via finite differences the analytical gradient and Jacobian of vector mapping $f(x) = Ax / \\|x\\|_2$.", "subtopics": ["9.7.1 Functions $f: \\mathbb{R}^n \\to \\mathbb{R}$: partial derivatives, gradient vector $\\nabla f(x)$, and steepness interpretation", "9.7.2 Directional derivatives: $D_v f(x) = \\nabla f(x)^T v$; gradient as the direction of steepest ascent", "9.7.3 Vector-valued functions $f: \\mathbb{R}^n \\to \\mathbb{R}^m$: the Jacobian matrix $J \\in \\mathbb{R}^{m \\times n}$ of all first-order partials", "9.7.4 Matrix calculus conventions: numerator layout (Jacobian formulation) vs denominator layout (gradient formulation)", "9.7.5 Vector-Jacobian Products (VJP): why reverse-mode automatic differentiation computes $v^T J$ rather than full $J$", "9.7.6 Jacobian-Vector Products (JVP): forward-mode automatic differentiation and directional derivative evaluation"]}'::jsonb, '["Explain how this implementation prevents: Mixing numerator and denominator layout conventions mid-derivation, yielding transposed matrix gradient dimensions.", "How does Multivariate Differential Calculus: Gradients, Jacobians & Directional Derivatives scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-8', 'phase-09-lesson-08-the-multivariable-chain-rule-computationa', 'module-4', 8, 'Lesson 4.8: The Multivariable Chain Rule & Computational Graphs', 'Prerequisites: Lesson 9.7', 'Prerequisites: Lesson 9.7 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 400.0, '# Lesson 9.8: The Multivariable Chain Rule & Computational Graphs

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.7
- **Subtopics**:
  - `9.8.1` Univariate chain rule review: $(f \circ g)''(x) = f''(g(x)) g''(x)$
  - `9.8.2` Multivariable chain rule: composing vector functions $z = f(y)$ where $y = g(x)$; Jacobian product $J_{z,x} = J_{z,y} J_{y,x}$
  - `9.8.3` Computational Directed Acyclic Graphs (DAG): nodes as variables/operations, directed edges as data dependencies
  - `9.8.4` Forward accumulation (Forward-Mode AD): propagating tangent vectors along DAG from inputs to outputs ($O(n)$ passes for $n$ inputs)
  - `9.8.5` Reverse accumulation (Reverse-Mode AD / Backpropagation): propagating adjoint vectors backward from output scalar to inputs ($O(1)$ pass)
  - `9.8.6` Why deep learning uses reverse-mode: neural loss functions map millions of parameters ($\mathbb{R}^n$) to a single scalar loss ($\mathbb{R}$)
- **Key Failure Modes & Edge Cases**: Forward-mode AD computing gradients parameter-by-parameter, resulting in millions of forward passes instead of one reverse pass.
- **Verification & Mastery Check**: Construct a DAG computation graph on paper and evaluate forward values and reverse adjoints step-by-step for a non-trivial function.
- **Project Application**: GradFlow: Computational graph DAG architecture.', '{"solution.py": "# Phase 9 // Lesson 9.8: The Multivariable Chain Rule & Computational Graphs\n\ndef solve():\n    \"\"\"\n    Verification: Construct a DAG computation graph on paper and evaluate forward values and reverse adjoints step-by-\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.8", "subtopics_count": 6, "verification_criteria": "Construct a DAG computation graph on paper and evaluate forward values and reverse adjoints step-by-step for a non-trivial function.", "subtopics": ["9.8.1 Univariate chain rule review: $(f \\circ g)''(x) = f''(g(x)) g''(x)$", "9.8.2 Multivariable chain rule: composing vector functions $z = f(y)$ where $y = g(x)$; Jacobian product $J_{z,x} = J_{z,y} J_{y,x}$", "9.8.3 Computational Directed Acyclic Graphs (DAG): nodes as variables/operations, directed edges as data dependencies", "9.8.4 Forward accumulation (Forward-Mode AD): propagating tangent vectors along DAG from inputs to outputs ($O(n)$ passes for $n$ inputs)", "9.8.5 Reverse accumulation (Reverse-Mode AD / Backpropagation): propagating adjoint vectors backward from output scalar to inputs ($O(1)$ pass)", "9.8.6 Why deep learning uses reverse-mode: neural loss functions map millions of parameters ($\\mathbb{R}^n$) to a single scalar loss ($\\mathbb{R}$)"]}'::jsonb, '["Explain how this implementation prevents: Forward-mode AD computing gradients parameter-by-parameter, resulting in millions of forward passes instead of one rever", "How does The Multivariable Chain Rule & Computational Graphs scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-9', 'phase-09-lesson-09-second-order-calculus-the-hessian-matrix-', 'module-4', 9, 'Lesson 4.9: Second-Order Calculus: The Hessian Matrix, Curvature & Taylor Approximations', 'Prerequisites: Lesson 9.7', 'Prerequisites: Lesson 9.7 | Subtopics: 6 items', 'Systems project application', 280, 10, 2250.0, 450.0, '# Lesson 9.9: Second-Order Calculus: The Hessian Matrix, Curvature & Taylor Approximations

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.7
- **Subtopics**:
  - `9.9.1` Second-order partial derivatives and Clairaut''s Schwarz Theorem: symmetry of mixed partials ($\frac{\partial^2 f}{\partial x_i \partial x_j} = \frac{\partial^2 f}{\partial x_j \partial x_i}$)
  - `9.9.2` The Hessian matrix $H \in \mathbb{R}^{n \times n}$: definition, symmetry, and representing local quadratic curvature
  - `9.9.3` Multivariable Taylor series expansions: 1st-order (linear tangent plane) and 2nd-order (quadratic approximation)
  - `9.9.4` Classifying stationary points ($\nabla f(x) = 0$): positive definite $H$ (local minimum), negative definite (maximum), indefinite (saddle point)
  - `9.9.5` Curvature along unit direction $v$: directional second derivative $v^T H v$; condition number of Hessian and ill-conditioned ravines
  - `9.9.6` Hessian-Free optimization and Hessian-Vector Products (HVP): computing $H v$ without storing the $O(n^2)$ full Hessian matrix
- **Key Failure Modes & Edge Cases**: Assuming local zero-gradient points are local minima in high dimensions, ignoring the prevalence of high-dimensional saddle points.
- **Verification & Mastery Check**: Compute the Hessian matrix of the Rosenbrock function; analyze its condition number and demonstrate gradient descent oscillations.
- **Project Application**: GradFlow: Curvature analysis and numerical verification.', '{"solution.py": "# Phase 9 // Lesson 9.9: Second-Order Calculus: The Hessian Matrix, Curvature & Taylor Approximations\n\ndef solve():\n    \"\"\"\n    Verification: Compute the Hessian matrix of the Rosenbrock function; analyze its condition number and demonstrate \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.9", "subtopics_count": 6, "verification_criteria": "Compute the Hessian matrix of the Rosenbrock function; analyze its condition number and demonstrate gradient descent oscillations.", "subtopics": ["9.9.1 Second-order partial derivatives and Clairaut''s Schwarz Theorem: symmetry of mixed partials ($\\frac{\\partial^2 f}{\\partial x_i \\partial x_j} = \\frac{\\partial^2 f}{\\partial x_j \\partial x_i}$)", "9.9.2 The Hessian matrix $H \\in \\mathbb{R}^{n \\times n}$: definition, symmetry, and representing local quadratic curvature", "9.9.3 Multivariable Taylor series expansions: 1st-order (linear tangent plane) and 2nd-order (quadratic approximation)", "9.9.4 Classifying stationary points ($\\nabla f(x) = 0$): positive definite $H$ (local minimum), negative definite (maximum), indefinite (saddle point)", "9.9.5 Curvature along unit direction $v$: directional second derivative $v^T H v$; condition number of Hessian and ill-conditioned ravines", "9.9.6 Hessian-Free optimization and Hessian-Vector Products (HVP): computing $H v$ without storing the $O(n^2)$ full Hessian matrix"]}'::jsonb, '["Explain how this implementation prevents: Assuming local zero-gradient points are local minima in high dimensions, ignoring the prevalence of high-dimensional sad", "How does Second-Order Calculus: The Hessian Matrix, Curvature & Taylor Approximations scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-10', 'phase-09-lesson-10-probability-theory-for-machine-learning-r', 'module-4', 10, 'Lesson 4.10: Probability Theory for Machine Learning: Random Variables, Densities & Independence', 'Prerequisites: Phase 2, Phase 3', 'Prerequisites: Phase 2, Phase 3 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 500.0, '# Lesson 9.10: Probability Theory for Machine Learning: Random Variables, Densities & Independence

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 2, Phase 3
- **Subtopics**:
  - `9.10.1` Probability spaces, axioms of probability, conditional probability, and Bayes'' Theorem ($P(A|B) = \frac{P(B|A)P(A)}{P(B)}$)
  - `9.10.2` Discrete random variables: PMF, CDF, Bernoulli, Binomial, and Categorical distributions
  - `9.10.3` Continuous random variables: PDF, CDF, Uniform, and Gaussian (Normal) distributions
  - `9.10.4` Expectation, variance, covariance, and correlation matrix: linearity of expectation ($\mathbb{E}[aX + bY] = a\mathbb{E}[X] + b\mathbb{E}[Y]$)
  - `9.10.5` Multivariate Gaussian distribution: mean vector $\mu$, covariance matrix $\Sigma$, and geometric ellipse contours
  - `9.10.6` Independence vs Uncorrelatedness: why zero covariance does not imply statistical independence for non-Gaussian variables
- **Key Failure Modes & Edge Cases**: Confusing probability density with probability mass (PDF values can exceed 1.0); dividing by singular covariance matrices.
- **Verification & Mastery Check**: Implement a Multivariate Gaussian probability density evaluator from scratch in NumPy with Cholesky-stabilized determinant computation.
- **Project Application**: GradFlow: Probabilistic foundations for machine learning.', '{"solution.py": "# Phase 9 // Lesson 9.10: Probability Theory for Machine Learning: Random Variables, Densities & Independence\n\ndef solve():\n    \"\"\"\n    Verification: Implement a Multivariate Gaussian probability density evaluator from scratch in NumPy with Cholesky-\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.10", "subtopics_count": 6, "verification_criteria": "Implement a Multivariate Gaussian probability density evaluator from scratch in NumPy with Cholesky-stabilized determinant computation.", "subtopics": ["9.10.1 Probability spaces, axioms of probability, conditional probability, and Bayes'' Theorem ($P(A|B) = \\frac{P(B|A)P(A)}{P(B)}$)", "9.10.2 Discrete random variables: PMF, CDF, Bernoulli, Binomial, and Categorical distributions", "9.10.3 Continuous random variables: PDF, CDF, Uniform, and Gaussian (Normal) distributions", "9.10.4 Expectation, variance, covariance, and correlation matrix: linearity of expectation ($\\mathbb{E}[aX + bY] = a\\mathbb{E}[X] + b\\mathbb{E}[Y]$)", "9.10.5 Multivariate Gaussian distribution: mean vector $\\mu$, covariance matrix $\\Sigma$, and geometric ellipse contours", "9.10.6 Independence vs Uncorrelatedness: why zero covariance does not imply statistical independence for non-Gaussian variables"]}'::jsonb, '["Explain how this implementation prevents: Confusing probability density with probability mass (PDF values can exceed 1.0); dividing by singular covariance matrice", "How does Probability Theory for Machine Learning: Random Variables, Densities & Independence scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-11', 'phase-09-lesson-11-information-theory-entropy-cross-entropy-', 'module-4', 11, 'Lesson 4.11: Information Theory: Entropy, Cross-Entropy & Kullback-Leibler (KL) Divergence', 'Prerequisites: Lesson 9.10', 'Prerequisites: Lesson 9.10 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 550.0, '# Lesson 9.11: Information Theory: Entropy, Cross-Entropy & Kullback-Leibler (KL) Divergence

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.10
- **Subtopics**:
  - `9.11.1` Self-information (surprisal): $I(x) = -\log_2 P(x)$; Shannon Entropy $H(P) = -\sum_x P(x) \log P(x)$ as expected information content
  - `9.11.2` Joint entropy, conditional entropy, and mutual information: $I(X; Y) = H(X) - H(X|Y)$ measuring shared information
  - `9.11.3` Kullback-Leibler (KL) Divergence: $D_{KL}(P \parallel Q) = \sum_x P(x) \log \frac{P(x)}{Q(x)}$ measuring relative entropy between distributions
  - `9.11.4` Properties of KL Divergence: non-negativity (Gibbs'' inequality: $D_{KL} \ge 0$), asymmetry ($D_{KL}(P \parallel Q) \neq D_{KL}(Q \parallel P)$)
  - `9.11.5` Cross-Entropy: $H(P, Q) = H(P) + D_{KL}(P \parallel Q) = -\sum_x P(x) \log Q(x)$; relationship to maximum likelihood estimation
  - `9.11.6` Forward KL (mode-covering) vs Reverse KL (mode-seeking) behavior in variational inference and generative modeling
- **Key Failure Modes & Edge Cases**: Treating KL divergence as a distance metric despite its asymmetry ($D_{KL}(P \parallel Q) \neq D_{KL}(Q \parallel P)$).
- **Verification & Mastery Check**: Implement Shannon Entropy, Cross-Entropy, and KL Divergence functions in Python; demonstrate forward vs reverse KL mode fitting.
- **Project Application**: TransformerLab: Cross-entropy loss formulation and attention entropy analysis.', '{"solution.py": "# Phase 9 // Lesson 9.11: Information Theory: Entropy, Cross-Entropy & Kullback-Leibler (KL) Divergence\n\ndef solve():\n    \"\"\"\n    Verification: Implement Shannon Entropy, Cross-Entropy, and KL Divergence functions in Python; demonstrate forward\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.11", "subtopics_count": 6, "verification_criteria": "Implement Shannon Entropy, Cross-Entropy, and KL Divergence functions in Python; demonstrate forward vs reverse KL mode fitting.", "subtopics": ["9.11.1 Self-information (surprisal): $I(x) = -\\log_2 P(x)$; Shannon Entropy $H(P) = -\\sum_x P(x) \\log P(x)$ as expected information content", "9.11.2 Joint entropy, conditional entropy, and mutual information: $I(X; Y) = H(X) - H(X|Y)$ measuring shared information", "9.11.3 Kullback-Leibler (KL) Divergence: $D_{KL}(P \\parallel Q) = \\sum_x P(x) \\log \\frac{P(x)}{Q(x)}$ measuring relative entropy between distributions", "9.11.4 Properties of KL Divergence: non-negativity (Gibbs'' inequality: $D_{KL} \\ge 0$), asymmetry ($D_{KL}(P \\parallel Q) \\neq D_{KL}(Q \\parallel P)$)", "9.11.5 Cross-Entropy: $H(P, Q) = H(P) + D_{KL}(P \\parallel Q) = -\\sum_x P(x) \\log Q(x)$; relationship to maximum likelihood estimation", "9.11.6 Forward KL (mode-covering) vs Reverse KL (mode-seeking) behavior in variational inference and generative modeling"]}'::jsonb, '["Explain how this implementation prevents: Treating KL divergence as a distance metric despite its asymmetry ($D_{KL}(P \\parallel Q) \\neq D_{KL}(Q \\parallel P)$).", "How does Information Theory: Entropy, Cross-Entropy & Kullback-Leibler (KL) Divergence scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-12', 'phase-09-lesson-12-statistical-estimators-maximum-likelihood', 'module-4', 12, 'Lesson 4.12: Statistical Estimators: Maximum Likelihood (MLE) & Maximum A Posteriori (MAP)', 'Prerequisites: Lesson 9.10, Lesson 9.11', 'Prerequisites: Lesson 9.10, Lesson 9.11 | Subtopics: 6 items', 'Systems project application', 280, 10, 2250.0, 600.0, '# Lesson 9.12: Statistical Estimators: Maximum Likelihood (MLE) & Maximum A Posteriori (MAP)

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.10, Lesson 9.11
- **Subtopics**:
  - `9.12.1` Parametric estimation: estimating underlying population parameters $\theta$ from observed data samples $\mathcal{D}$
  - `9.12.2` Likelihood function $L(\theta; \mathcal{D})$ and Log-Likelihood $\ell(\theta) = \sum_{i=1}^N \log p(x_i | \theta)$ under i.i.d. assumptions
  - `9.12.3` Maximum Likelihood Estimation (MLE): maximizing log-likelihood; connecting Gaussian MLE to Ordinary Least Squares (OLS)
  - `9.12.4` Connecting Categorical MLE to Cross-Entropy loss in classification models
  - `9.12.5` Maximum A Posteriori (MAP) estimation: incorporating prior distributions $p(\theta)$ via Bayes'' rule ($\theta_{MAP} = \arg\max [\log p(\mathcal{D}|\theta) + \log p(\theta)]$)
  - `9.12.6` Regularization equivalence: Gaussian prior ($L_2$ / Ridge) vs Laplace prior ($L_1$ / Lasso) on weights
- **Key Failure Modes & Edge Cases**: Maximizing raw likelihood instead of log-likelihood, resulting in floating-point underflow when multiplying small probabilities.
- **Verification & Mastery Check**: Derive analytically and implement in Python the MLE and MAP estimators for linear regression with Gaussian and Laplace priors.
- **Project Application**: GradFlow: Loss function probabilistic derivation suite.', '{"solution.py": "# Phase 9 // Lesson 9.12: Statistical Estimators: Maximum Likelihood (MLE) & Maximum A Posteriori (MAP)\n\ndef solve():\n    \"\"\"\n    Verification: Derive analytically and implement in Python the MLE and MAP estimators for linear regression with Ga\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.12", "subtopics_count": 6, "verification_criteria": "Derive analytically and implement in Python the MLE and MAP estimators for linear regression with Gaussian and Laplace priors.", "subtopics": ["9.12.1 Parametric estimation: estimating underlying population parameters $\\theta$ from observed data samples $\\mathcal{D}$", "9.12.2 Likelihood function $L(\\theta; \\mathcal{D})$ and Log-Likelihood $\\ell(\\theta) = \\sum_{i=1}^N \\log p(x_i | \\theta)$ under i.i.d. assumptions", "9.12.3 Maximum Likelihood Estimation (MLE): maximizing log-likelihood; connecting Gaussian MLE to Ordinary Least Squares (OLS)", "9.12.4 Connecting Categorical MLE to Cross-Entropy loss in classification models", "9.12.5 Maximum A Posteriori (MAP) estimation: incorporating prior distributions $p(\\theta)$ via Bayes'' rule ($\\theta_{MAP} = \\arg\\max [\\log p(\\mathcal{D}|\\theta) + \\log p(\\theta)]$)", "9.12.6 Regularization equivalence: Gaussian prior ($L_2$ / Ridge) vs Laplace prior ($L_1$ / Lasso) on weights"]}'::jsonb, '["Explain how this implementation prevents: Maximizing raw likelihood instead of log-likelihood, resulting in floating-point underflow when multiplying small probab", "How does Statistical Estimators: Maximum Likelihood (MLE) & Maximum A Posteriori (MAP) scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-13', 'phase-09-lesson-13-neural-network-foundations-the-perceptron', 'module-4', 13, 'Lesson 4.13: Neural Network Foundations: The Perceptron, Multilayer Perceptrons (MLP) & Universal Approximation', 'Prerequisites: Lesson 9.1, Lesson 9.7', 'Prerequisites: Lesson 9.1, Lesson 9.7 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 650.0, '# Lesson 9.13: Neural Network Foundations: The Perceptron, Multilayer Perceptrons (MLP) & Universal Approximation

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.1, Lesson 9.7
- **Subtopics**:
  - `9.13.1` The McCulloch-Pitts neuron and Rosenblatt Perceptron: weights, bias, step activation, and linear classification boundaries
  - `9.13.2` The XOR problem: Minsky & Papert''s proof of perceptron linear limitations and the necessity of hidden layers
  - `9.13.3` Multilayer Perceptron (MLP) architecture: input layer, hidden layers, output layer, and fully connected affine transformations ($z = Wx + b$)
  - `9.13.4` The Universal Approximation Theorem (Cybenko, Hornik): single hidden layer with non-linear activation approximating continuous functions
  - `9.13.5` Depth vs Width: why deep neural networks achieve exponential representational efficiency over shallow wide networks
  - `9.13.6` Matrix formulation of batch forward passes: $Z = X W^T + b$ where $X \in \mathbb{R}^{B \times d_{in}}$ and $W \in \mathbb{R}^{d_{out} \times d_{in}}$
- **Key Failure Modes & Edge Cases**: Omitting the bias vector $b$, constraining linear decision boundaries to pass strictly through the coordinate origin.
- **Verification & Mastery Check**: Build a 2-layer MLP from scratch in pure Python (no external libraries) that successfully learns the non-linear XOR truth table.
- **Project Application**: GradFlow: Fundamental Multi-Layer Perceptron implementation.', '{"solution.py": "# Phase 9 // Lesson 9.13: Neural Network Foundations: The Perceptron, Multilayer Perceptrons (MLP) & Universal Approximation\n\ndef solve():\n    \"\"\"\n    Verification: Build a 2-layer MLP from scratch in pure Python (no external libraries) that successfully learns the\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.13", "subtopics_count": 6, "verification_criteria": "Build a 2-layer MLP from scratch in pure Python (no external libraries) that successfully learns the non-linear XOR truth table.", "subtopics": ["9.13.1 The McCulloch-Pitts neuron and Rosenblatt Perceptron: weights, bias, step activation, and linear classification boundaries", "9.13.2 The XOR problem: Minsky & Papert''s proof of perceptron linear limitations and the necessity of hidden layers", "9.13.3 Multilayer Perceptron (MLP) architecture: input layer, hidden layers, output layer, and fully connected affine transformations ($z = Wx + b$)", "9.13.4 The Universal Approximation Theorem (Cybenko, Hornik): single hidden layer with non-linear activation approximating continuous functions", "9.13.5 Depth vs Width: why deep neural networks achieve exponential representational efficiency over shallow wide networks", "9.13.6 Matrix formulation of batch forward passes: $Z = X W^T + b$ where $X \\in \\mathbb{R}^{B \\times d_{in}}$ and $W \\in \\mathbb{R}^{d_{out} \\times d_{in}}$"]}'::jsonb, '["Explain how this implementation prevents: Omitting the bias vector $b$, constraining linear decision boundaries to pass strictly through the coordinate origin.", "How does Neural Network Foundations: The Perceptron, Multilayer Perceptrons (MLP) & Universal Approximation scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-14', 'phase-09-lesson-14-activation-functions-sigmoid-tanh-relu-ge', 'module-4', 14, 'Lesson 4.14: Activation Functions: Sigmoid, Tanh, ReLU, GELU & SwiGLU', 'Prerequisites: Lesson 9.13', 'Prerequisites: Lesson 9.13 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 700.0, '# Lesson 9.14: Activation Functions: Sigmoid, Tanh, ReLU, GELU & SwiGLU

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.13
- **Subtopics**:
  - `9.14.1` Role of non-linear activations: breaking linearity to enable multi-layer feature representation learning
  - `9.14.2` Sigmoid $\sigma(z) = \frac{1}{1 + e^{-z}}$: saturation at tails, vanishing gradients (max derivative 0.25), and non-zero-centered outputs
  - `9.14.3` Hyperbolic Tangent $\tanh(z)$: zero-centered outputs, saturation at tails, and relation to sigmoid ($\tanh(z) = 2\sigma(2z) - 1$)
  - `9.14.4` Rectified Linear Unit (ReLU) $f(z) = \max(0, z)$: constant gradient for positive inputs, computational efficiency, and ''Dying ReLU'' problem
  - `9.14.5` Leaky ReLU and Parametric ReLU (PReLU): introducing non-zero slope for negative inputs to prevent dead neurons
  - `9.14.6` Modern Transformer activations: Gaussian Error Linear Unit (GELU) and Swish/SiLU; SwiGLU gated linear units in LLaMA
- **Key Failure Modes & Edge Cases**: Using sigmoid activations throughout deep 10-layer networks, causing complete vanishing of gradients during backpropagation.
- **Verification & Mastery Check**: Implement Sigmoid, Tanh, ReLU, GELU, and SwiGLU activations along with their exact analytical derivatives in NumPy.
- **Project Application**: TransformerLab: Activation function layer suite.', '{"solution.py": "# Phase 9 // Lesson 9.14: Activation Functions: Sigmoid, Tanh, ReLU, GELU & SwiGLU\n\ndef solve():\n    \"\"\"\n    Verification: Implement Sigmoid, Tanh, ReLU, GELU, and SwiGLU activations along with their exact analytical deriva\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.14", "subtopics_count": 6, "verification_criteria": "Implement Sigmoid, Tanh, ReLU, GELU, and SwiGLU activations along with their exact analytical derivatives in NumPy.", "subtopics": ["9.14.1 Role of non-linear activations: breaking linearity to enable multi-layer feature representation learning", "9.14.2 Sigmoid $\\sigma(z) = \\frac{1}{1 + e^{-z}}$: saturation at tails, vanishing gradients (max derivative 0.25), and non-zero-centered outputs", "9.14.3 Hyperbolic Tangent $\\tanh(z)$: zero-centered outputs, saturation at tails, and relation to sigmoid ($\\tanh(z) = 2\\sigma(2z) - 1$)", "9.14.4 Rectified Linear Unit (ReLU) $f(z) = \\max(0, z)$: constant gradient for positive inputs, computational efficiency, and ''Dying ReLU'' problem", "9.14.5 Leaky ReLU and Parametric ReLU (PReLU): introducing non-zero slope for negative inputs to prevent dead neurons", "9.14.6 Modern Transformer activations: Gaussian Error Linear Unit (GELU) and Swish/SiLU; SwiGLU gated linear units in LLaMA"]}'::jsonb, '["Explain how this implementation prevents: Using sigmoid activations throughout deep 10-layer networks, causing complete vanishing of gradients during backpropagat", "How does Activation Functions: Sigmoid, Tanh, ReLU, GELU & SwiGLU scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-15', 'phase-09-lesson-15-loss-functions-mse-binary-cross-entropy-c', 'module-4', 15, 'Lesson 4.15: Loss Functions: MSE, Binary Cross-Entropy, Categorical Cross-Entropy & Softmax', 'Prerequisites: Lesson 9.11, Lesson 9.14', 'Prerequisites: Lesson 9.11, Lesson 9.14 | Subtopics: 6 items', 'Systems project application', 280, 10, 2250.0, 750.0, '# Lesson 9.15: Loss Functions: MSE, Binary Cross-Entropy, Categorical Cross-Entropy & Softmax

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.11, Lesson 9.14
- **Subtopics**:
  - `9.15.1` Mean Squared Error (MSE) loss: formulation, derivation from Gaussian MLE, sensitivity to outliers, and regression tasks
  - `9.15.2` Binary Cross-Entropy (BCE) loss: formulation, derivation from Bernoulli likelihood, and pairing with sigmoid output layer
  - `9.15.3` Softmax function: mapping arbitrary logits $z \in \mathbb{R}^K$ to a valid probability distribution over $K$ classes ($\sum p_i = 1$)
  - `9.15.4` Numerical stability of Softmax: subtracting maximum logit value ($z_i - \max(z)$) to prevent floating-point exponential overflow
  - `9.15.5` Categorical Cross-Entropy loss: $-\sum_{k=1}^K y_k \log p_k$; derivation from categorical distribution likelihood
  - `9.15.6` The combined Softmax + Cross-Entropy gradient: elegant derivation showing $\frac{\partial L}{\partial z_i} = p_i - y_i$
- **Key Failure Modes & Edge Cases**: Evaluating raw `np.exp(z)` in Softmax causing NaN/overflow crashes on large logit values ($z > 709$).
- **Verification & Mastery Check**: Implement a numerically stable fused Softmax-Cross-Entropy loss function and verify that its gradient simplifies to $\hat{y} - y$.
- **Project Application**: GradFlow: Core loss functions and numerical stability layer.', '{"solution.py": "# Phase 9 // Lesson 9.15: Loss Functions: MSE, Binary Cross-Entropy, Categorical Cross-Entropy & Softmax\n\ndef solve():\n    \"\"\"\n    Verification: Implement a numerically stable fused Softmax-Cross-Entropy loss function and verify that its gradien\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.15", "subtopics_count": 6, "verification_criteria": "Implement a numerically stable fused Softmax-Cross-Entropy loss function and verify that its gradient simplifies to $\\hat{y} - y$.", "subtopics": ["9.15.1 Mean Squared Error (MSE) loss: formulation, derivation from Gaussian MLE, sensitivity to outliers, and regression tasks", "9.15.2 Binary Cross-Entropy (BCE) loss: formulation, derivation from Bernoulli likelihood, and pairing with sigmoid output layer", "9.15.3 Softmax function: mapping arbitrary logits $z \\in \\mathbb{R}^K$ to a valid probability distribution over $K$ classes ($\\sum p_i = 1$)", "9.15.4 Numerical stability of Softmax: subtracting maximum logit value ($z_i - \\max(z)$) to prevent floating-point exponential overflow", "9.15.5 Categorical Cross-Entropy loss: $-\\sum_{k=1}^K y_k \\log p_k$; derivation from categorical distribution likelihood", "9.15.6 The combined Softmax + Cross-Entropy gradient: elegant derivation showing $\\frac{\\partial L}{\\partial z_i} = p_i - y_i$"]}'::jsonb, '["Explain how this implementation prevents: Evaluating raw `np.exp(z)` in Softmax causing NaN/overflow crashes on large logit values ($z > 709$).", "How does Loss Functions: MSE, Binary Cross-Entropy, Categorical Cross-Entropy & Softmax scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-16', 'phase-09-lesson-16-analytical-backpropagation-i-gradients-fo', 'module-4', 16, 'Lesson 4.16: Analytical Backpropagation I: Gradients for Linear Layers & Affine Transforms', 'Prerequisites: Lesson 9.7, Lesson 9.15', 'Prerequisites: Lesson 9.7, Lesson 9.15 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 800.0, '# Lesson 9.16: Analytical Backpropagation I: Gradients for Linear Layers & Affine Transforms

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.7, Lesson 9.15
- **Subtopics**:
  - `9.16.1` The scalar-by-matrix derivative: conventions, dimensions matching, and chain rule application
  - `9.16.2` Forward pass of linear layer: $Y = X W + b$ with shapes $X \in \mathbb{R}^{B \times D}$, $W \in \mathbb{R}^{D \times M}$, $b \in \mathbb{R}^{1 \times M}$
  - `9.16.3` Derivation of weight gradient: $\frac{\partial L}{\partial W} = X^T \frac{\partial L}{\partial Y}$ (dimensions $(D \times B) \times (B \times M) = (D \times M)$)
  - `9.16.4` Derivation of input gradient: $\frac{\partial L}{\partial X} = \frac{\partial L}{\partial Y} W^T$ (dimensions $(B \times M) \times (M \times D) = (B \times D)$)
  - `9.16.5` Derivation of bias gradient: $\frac{\partial L}{\partial b} = \sum_{i=1}^B \frac{\partial L}{\partial Y_{i,:}}$ (summing over batch dimension)
  - `9.16.6` Memory management: caching input activations $X$ and weights $W$ during forward pass for backward computation
- **Key Failure Modes & Edge Cases**: Transposing matrices incorrectly in backpropagation formulas, producing dimension mismatches or computing invalid gradients.
- **Verification & Mastery Check**: Derive and hand-code the forward and backward passes for a dense linear layer in NumPy; verify gradients via finite differences.
- **Project Application**: GradFlow: Dense Linear layer with exact analytical backprop.', '{"solution.py": "# Phase 9 // Lesson 9.16: Analytical Backpropagation I: Gradients for Linear Layers & Affine Transforms\n\ndef solve():\n    \"\"\"\n    Verification: Derive and hand-code the forward and backward passes for a dense linear layer in NumPy; verify gradi\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.16", "subtopics_count": 6, "verification_criteria": "Derive and hand-code the forward and backward passes for a dense linear layer in NumPy; verify gradients via finite differences.", "subtopics": ["9.16.1 The scalar-by-matrix derivative: conventions, dimensions matching, and chain rule application", "9.16.2 Forward pass of linear layer: $Y = X W + b$ with shapes $X \\in \\mathbb{R}^{B \\times D}$, $W \\in \\mathbb{R}^{D \\times M}$, $b \\in \\mathbb{R}^{1 \\times M}$", "9.16.3 Derivation of weight gradient: $\\frac{\\partial L}{\\partial W} = X^T \\frac{\\partial L}{\\partial Y}$ (dimensions $(D \\times B) \\times (B \\times M) = (D \\times M)$)", "9.16.4 Derivation of input gradient: $\\frac{\\partial L}{\\partial X} = \\frac{\\partial L}{\\partial Y} W^T$ (dimensions $(B \\times M) \\times (M \\times D) = (B \\times D)$)", "9.16.5 Derivation of bias gradient: $\\frac{\\partial L}{\\partial b} = \\sum_{i=1}^B \\frac{\\partial L}{\\partial Y_{i,:}}$ (summing over batch dimension)", "9.16.6 Memory management: caching input activations $X$ and weights $W$ during forward pass for backward computation"]}'::jsonb, '["Explain how this implementation prevents: Transposing matrices incorrectly in backpropagation formulas, producing dimension mismatches or computing invalid gradie", "How does Analytical Backpropagation I: Gradients for Linear Layers & Affine Transforms scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-17', 'phase-09-lesson-17-analytical-backpropagation-ii-end-to-end-', 'module-4', 17, 'Lesson 4.17: Analytical Backpropagation II: End-to-End 3-Layer Network by Hand', 'Prerequisites: Lesson 9.16', 'Prerequisites: Lesson 9.16 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 850.0, '# Lesson 9.17: Analytical Backpropagation II: End-to-End 3-Layer Network by Hand

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.16
- **Subtopics**:
  - `9.17.1` End-to-end forward architecture: $Z_1 = X W_1 + b_1$, $A_1 = \text{ReLU}(Z_1)$, $Z_2 = A_1 W_2 + b_2$, $\hat{Y} = \text{Softmax}(Z_2)$
  - `9.17.2` Loss calculation: $L = \text{CrossEntropy}(\hat{Y}, Y)$
  - `9.17.3` Step 1 backward: output logit gradient $\delta_2 = \frac{\partial L}{\partial Z_2} = \hat{Y} - Y$
  - `9.17.4` Step 2 backward: parameter gradients $\frac{\partial L}{\partial W_2} = A_1^T \delta_2$, $\frac{\partial L}{\partial b_2} = \text{sum}(\delta_2, \text{axis}=0)$
  - `9.17.5` Step 3 backward: hidden activation gradient $\frac{\partial L}{\partial A_1} = \delta_2 W_2^T$
  - `9.17.6` Step 4 backward: ReLU gate gradient $\delta_1 = \frac{\partial L}{\partial Z_1} = \frac{\partial L}{\partial A_1} \odot \mathbb{I}(Z_1 > 0)$, followed by $W_1, b_1$ gradients
- **Key Failure Modes & Edge Cases**: Computing ReLU backward gradient using post-activation values $A_1$ rather than pre-activation $Z_1$ when Leaky ReLU is introduced.
- **Verification & Mastery Check**: Implement a 3-layer neural network from scratch in NumPy with 100% manual backpropagation; train it to 98% accuracy on MNIST.
- **Project Application**: GradFlow: Fully verified manual MLP reference implementation.', '{"solution.py": "# Phase 9 // Lesson 9.17: Analytical Backpropagation II: End-to-End 3-Layer Network by Hand\n\ndef solve():\n    \"\"\"\n    Verification: Implement a 3-layer neural network from scratch in NumPy with 100% manual backpropagation; train it \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.17", "subtopics_count": 6, "verification_criteria": "Implement a 3-layer neural network from scratch in NumPy with 100% manual backpropagation; train it to 98% accuracy on MNIST.", "subtopics": ["9.17.1 End-to-end forward architecture: $Z_1 = X W_1 + b_1$, $A_1 = \\text{ReLU}(Z_1)$, $Z_2 = A_1 W_2 + b_2$, $\\hat{Y} = \\text{Softmax}(Z_2)$", "9.17.2 Loss calculation: $L = \\text{CrossEntropy}(\\hat{Y}, Y)$", "9.17.3 Step 1 backward: output logit gradient $\\delta_2 = \\frac{\\partial L}{\\partial Z_2} = \\hat{Y} - Y$", "9.17.4 Step 2 backward: parameter gradients $\\frac{\\partial L}{\\partial W_2} = A_1^T \\delta_2$, $\\frac{\\partial L}{\\partial b_2} = \\text{sum}(\\delta_2, \\text{axis}=0)$", "9.17.5 Step 3 backward: hidden activation gradient $\\frac{\\partial L}{\\partial A_1} = \\delta_2 W_2^T$", "9.17.6 Step 4 backward: ReLU gate gradient $\\delta_1 = \\frac{\\partial L}{\\partial Z_1} = \\frac{\\partial L}{\\partial A_1} \\odot \\mathbb{I}(Z_1 > 0)$, followed by $W_1, b_1$ gradients"]}'::jsonb, '["Explain how this implementation prevents: Computing ReLU backward gradient using post-activation values $A_1$ rather than pre-activation $Z_1$ when Leaky ReLU is ", "How does Analytical Backpropagation II: End-to-End 3-Layer Network by Hand scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-18', 'phase-09-lesson-18-numerical-gradient-checking-gradcheck-fin', 'module-4', 18, 'Lesson 4.18: Numerical Gradient Checking (GradCheck) & Finite Differences', 'Prerequisites: Lesson 9.7, Lesson 9.17', 'Prerequisites: Lesson 9.7, Lesson 9.17 | Subtopics: 6 items', 'Systems project application', 280, 10, 2250.0, 900.0, '# Lesson 9.18: Numerical Gradient Checking (GradCheck) & Finite Differences

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.7, Lesson 9.17
- **Subtopics**:
  - `9.18.1` Why gradient checking is essential: silent bugs in analytical backprop allowing networks to learn partially while degrading performance
  - `9.18.2` Finite difference approximations: Forward difference ($\frac{f(\theta + \epsilon) - f(\theta)}{\epsilon}$, error $O(\epsilon)$)
  - `9.18.3` Centered difference approximation: $\frac{f(\theta + \epsilon) - f(\theta - \epsilon)}{2\epsilon}$, error $O(\epsilon^2)$
  - `9.18.4` Choosing the perturbation size: why $\epsilon \approx 10^{-7}$ balances truncation error and floating-point cancellation error
  - `9.18.5` Relative error metric: $\frac{\|\nabla_{analytical} - \nabla_{numerical}\|_2}{\|\nabla_{analytical}\|_2 + \|\nabla_{numerical}\|_2 + 10^{-15}}$
  - `9.18.6` Failure triage: interpreting relative errors ($<10^{-7}$ perfect, $>10^{-2}$ major bug in analytical backprop)
- **Key Failure Modes & Edge Cases**: Using forward difference instead of centered difference, leading to false-positive gradient bug warnings.
- **Verification & Mastery Check**: Build a universal `grad_check` utility function verifying arbitrary tensor layers against centered finite differences.
- **Project Application**: GradFlow: Universal gradient checking verification suite.', '{"solution.py": "# Phase 9 // Lesson 9.18: Numerical Gradient Checking (GradCheck) & Finite Differences\n\ndef solve():\n    \"\"\"\n    Verification: Build a universal `grad_check` utility function verifying arbitrary tensor layers against centered f\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.18", "subtopics_count": 6, "verification_criteria": "Build a universal `grad_check` utility function verifying arbitrary tensor layers against centered finite differences.", "subtopics": ["9.18.1 Why gradient checking is essential: silent bugs in analytical backprop allowing networks to learn partially while degrading performance", "9.18.2 Finite difference approximations: Forward difference ($\\frac{f(\\theta + \\epsilon) - f(\\theta)}{\\epsilon}$, error $O(\\epsilon)$)", "9.18.3 Centered difference approximation: $\\frac{f(\\theta + \\epsilon) - f(\\theta - \\epsilon)}{2\\epsilon}$, error $O(\\epsilon^2)$", "9.18.4 Choosing the perturbation size: why $\\epsilon \\approx 10^{-7}$ balances truncation error and floating-point cancellation error", "9.18.5 Relative error metric: $\\frac{\\|\\nabla_{analytical} - \\nabla_{numerical}\\|_2}{\\|\\nabla_{analytical}\\|_2 + \\|\\nabla_{numerical}\\|_2 + 10^{-15}}$", "9.18.6 Failure triage: interpreting relative errors ($<10^{-7}$ perfect, $>10^{-2}$ major bug in analytical backprop)"]}'::jsonb, '["Explain how this implementation prevents: Using forward difference instead of centered difference, leading to false-positive gradient bug warnings.", "How does Numerical Gradient Checking (GradCheck) & Finite Differences scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-19', 'phase-09-lesson-19-weight-initialization-dynamics-vanishing-', 'module-4', 19, 'Lesson 4.19: Weight Initialization Dynamics: Vanishing/Exploding Gradients & He/Xavier', 'Prerequisites: Lesson 9.10, Lesson 9.16', 'Prerequisites: Lesson 9.10, Lesson 9.16 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 950.0, '# Lesson 9.19: Weight Initialization Dynamics: Vanishing/Exploding Gradients & He/Xavier

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.10, Lesson 9.16
- **Subtopics**:
  - `9.19.1` The initialization problem: zero initialization symmetry breaking failure, too small (vanishing), too large (exploding)
  - `9.19.2` Variance propagation through layers: deriving $\text{Var}(y) = n \cdot \text{Var}(w) \cdot \text{Var}(x)$ under zero-mean inputs
  - `9.19.3` Xavier (Glorot) Initialization: preserving variance across forward and backward passes for tanh/sigmoid: $W \sim \mathcal{N}\left(0, \frac{2}{n_{in} + n_{out}}\right)$
  - `9.19.4` He (Kaiming) Initialization: accounting for half-rectification in ReLU activations: $W \sim \mathcal{N}\left(0, \frac{2}{n_{in}}\right)$
  - `9.19.5` LeCun Initialization: optimal scaling for SELU self-normalizing networks
  - `9.19.6` Modern LLM initialization: scaling residual projection weights by $\frac{1}{\sqrt{2 \times N_{layers}}}$ to stabilize deep Transformer training
- **Key Failure Modes & Edge Cases**: Initializing weights with standard normal distribution $\mathcal{N}(0, 1)$, causing activations to explode to infinity within 6 layers.
- **Verification & Mastery Check**: Simulate activation and gradient variance through 50 layers with different initializations; prove He initialization prevents collapse.
- **Project Application**: GradFlow: Initializer module (He, Xavier, Normal, Uniform).', '{"solution.py": "# Phase 9 // Lesson 9.19: Weight Initialization Dynamics: Vanishing/Exploding Gradients & He/Xavier\n\ndef solve():\n    \"\"\"\n    Verification: Simulate activation and gradient variance through 50 layers with different initializations; prove He\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.19", "subtopics_count": 6, "verification_criteria": "Simulate activation and gradient variance through 50 layers with different initializations; prove He initialization prevents collapse.", "subtopics": ["9.19.1 The initialization problem: zero initialization symmetry breaking failure, too small (vanishing), too large (exploding)", "9.19.2 Variance propagation through layers: deriving $\\text{Var}(y) = n \\cdot \\text{Var}(w) \\cdot \\text{Var}(x)$ under zero-mean inputs", "9.19.3 Xavier (Glorot) Initialization: preserving variance across forward and backward passes for tanh/sigmoid: $W \\sim \\mathcal{N}\\left(0, \\frac{2}{n_{in} + n_{out}}\\right)$", "9.19.4 He (Kaiming) Initialization: accounting for half-rectification in ReLU activations: $W \\sim \\mathcal{N}\\left(0, \\frac{2}{n_{in}}\\right)$", "9.19.5 LeCun Initialization: optimal scaling for SELU self-normalizing networks", "9.19.6 Modern LLM initialization: scaling residual projection weights by $\\frac{1}{\\sqrt{2 \\times N_{layers}}}$ to stabilize deep Transformer training"]}'::jsonb, '["Explain how this implementation prevents: Initializing weights with standard normal distribution $\\mathcal{N}(0, 1)$, causing activations to explode to infinity w", "How does Weight Initialization Dynamics: Vanishing/Exploding Gradients & He/Xavier scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-20', 'phase-09-lesson-20-batch-normalization-layer-normalization-i', 'module-4', 20, 'Lesson 4.20: Batch Normalization & Layer Normalization Internals', 'Prerequisites: Lesson 9.10, Lesson 9.19', 'Prerequisites: Lesson 9.10, Lesson 9.19 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 1000.0, '# Lesson 9.20: Batch Normalization & Layer Normalization Internals

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.10, Lesson 9.19
- **Subtopics**:
  - `9.20.1` Internal Covariate Shift hypothesis vs smoothing the optimization landscape: how normalization stabilizes loss surfaces
  - `9.20.2` Batch Normalization (BatchNorm): batch mean, batch variance, normalize, affine scale and shift ($\gamma \hat{x} + \beta$)
  - `9.20.3` Running statistics in BatchNorm: tracking running_mean and running_var via momentum for evaluation mode inference
  - `9.20.4` Failure modes of BatchNorm: small batch sizes, sequence modeling disparity, and training/eval mode mismatch bugs
  - `9.20.5` Layer Normalization (LayerNorm): normalizing across feature dimensions per sample independently of batch size
  - `9.20.6` Analytical backpropagation through LayerNorm: deriving gradients with respect to inputs, gamma, and beta
- **Key Failure Modes & Edge Cases**: Forgetting to switch BatchNorm from training mode to evaluation mode, producing catastrophic random predictions during production inference.
- **Verification & Mastery Check**: Implement LayerNorm and BatchNorm from scratch in NumPy, including both forward pass and complete analytical backward gradient passes.
- **Project Application**: TransformerLab: Pre-LayerNorm and RMSNorm layers.', '{"solution.py": "# Phase 9 // Lesson 9.20: Batch Normalization & Layer Normalization Internals\n\ndef solve():\n    \"\"\"\n    Verification: Implement LayerNorm and BatchNorm from scratch in NumPy, including both forward pass and complete an\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.20", "subtopics_count": 6, "verification_criteria": "Implement LayerNorm and BatchNorm from scratch in NumPy, including both forward pass and complete analytical backward gradient passes.", "subtopics": ["9.20.1 Internal Covariate Shift hypothesis vs smoothing the optimization landscape: how normalization stabilizes loss surfaces", "9.20.2 Batch Normalization (BatchNorm): batch mean, batch variance, normalize, affine scale and shift ($\\gamma \\hat{x} + \\beta$)", "9.20.3 Running statistics in BatchNorm: tracking running_mean and running_var via momentum for evaluation mode inference", "9.20.4 Failure modes of BatchNorm: small batch sizes, sequence modeling disparity, and training/eval mode mismatch bugs", "9.20.5 Layer Normalization (LayerNorm): normalizing across feature dimensions per sample independently of batch size", "9.20.6 Analytical backpropagation through LayerNorm: deriving gradients with respect to inputs, gamma, and beta"]}'::jsonb, '["Explain how this implementation prevents: Forgetting to switch BatchNorm from training mode to evaluation mode, producing catastrophic random predictions during p", "How does Batch Normalization & Layer Normalization Internals scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-21', 'phase-09-lesson-21-optimization-fundamentals-gradient-descen', 'module-4', 21, 'Lesson 4.21: Optimization Fundamentals: Gradient Descent & Stochastic Gradient Descent (SGD)', 'Prerequisites: Lesson 9.7, Lesson 9.16', 'Prerequisites: Lesson 9.7, Lesson 9.16 | Subtopics: 6 items', 'Systems project application', 280, 10, 2250.0, 1050.0, '# Lesson 9.21: Optimization Fundamentals: Gradient Descent & Stochastic Gradient Descent (SGD)

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.7, Lesson 9.16
- **Subtopics**:
  - `9.21.1` Optimization landscape: convex functions vs non-convex neural network loss surfaces, local minima, and saddle points
  - `9.21.2` Batch Gradient Descent (BGD): updating parameters over full dataset; stability vs extreme computational cost on large data
  - `9.21.3` Stochastic Gradient Descent (SGD): single-sample parameter updates; high variance, noisy gradient estimates, escaping saddle points
  - `9.21.4` Mini-Batch SGD: sweet spot balancing computational parallelism on GPUs with gradient estimation stability ($B=32, 64, 256$)
  - `9.21.5` Learning rate (step size $\eta$): divergence from overly high $\eta$, creeping stagnation from overly low $\eta$
  - `9.21.6` Ill-conditioned ravines: why standard SGD oscillates violently perpendicular to steep valley walls while making slow progress along the valley floor
- **Key Failure Modes & Edge Cases**: Using an excessively high learning rate causing loss to diverge to infinity/NaN within the first few parameter update steps.
- **Verification & Mastery Check**: Implement a modular Mini-Batch SGD optimizer in pure NumPy with batch generation, epoch looping, and loss tracking.
- **Project Application**: GradFlow: Base optimizer class and SGD implementation.', '{"solution.py": "# Phase 9 // Lesson 9.21: Optimization Fundamentals: Gradient Descent & Stochastic Gradient Descent (SGD)\n\ndef solve():\n    \"\"\"\n    Verification: Implement a modular Mini-Batch SGD optimizer in pure NumPy with batch generation, epoch looping, and\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.21", "subtopics_count": 6, "verification_criteria": "Implement a modular Mini-Batch SGD optimizer in pure NumPy with batch generation, epoch looping, and loss tracking.", "subtopics": ["9.21.1 Optimization landscape: convex functions vs non-convex neural network loss surfaces, local minima, and saddle points", "9.21.2 Batch Gradient Descent (BGD): updating parameters over full dataset; stability vs extreme computational cost on large data", "9.21.3 Stochastic Gradient Descent (SGD): single-sample parameter updates; high variance, noisy gradient estimates, escaping saddle points", "9.21.4 Mini-Batch SGD: sweet spot balancing computational parallelism on GPUs with gradient estimation stability ($B=32, 64, 256$)", "9.21.5 Learning rate (step size $\\eta$): divergence from overly high $\\eta$, creeping stagnation from overly low $\\eta$", "9.21.6 Ill-conditioned ravines: why standard SGD oscillates violently perpendicular to steep valley walls while making slow progress along the valley floor"]}'::jsonb, '["Explain how this implementation prevents: Using an excessively high learning rate causing loss to diverge to infinity/NaN within the first few parameter update st", "How does Optimization Fundamentals: Gradient Descent & Stochastic Gradient Descent (SGD) scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-22', 'phase-09-lesson-22-advanced-optimizers-momentum-nesterov-rms', 'module-4', 22, 'Lesson 4.22: Advanced Optimizers: Momentum, Nesterov, RMSprop & AdamW', 'Prerequisites: Lesson 9.21', 'Prerequisites: Lesson 9.21 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 1100.0, '# Lesson 9.22: Advanced Optimizers: Momentum, Nesterov, RMSprop & AdamW

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.21
- **Subtopics**:
  - `9.22.1` Momentum: exponential moving average of past gradients ($v_t = \beta v_{t-1} + g_t$); dampening oscillations in ravines
  - `9.22.2` Nesterov Accelerated Gradient (NAG): computing gradient after looking ahead along current momentum vector
  - `9.22.3` RMSprop: adaptive learning rates dividing gradient by root-mean-square of running squared gradients ($s_t = \beta s_{t-1} + (1-\beta)g_t^2$)
  - `9.22.4` Adam (Adaptive Moment Estimation): combining 1st moment (momentum) and 2nd moment (RMSprop) with bias correction for initial steps
  - `9.22.5` Adam bias correction derivation: why dividing by $(1 - \beta_1^t)$ and $(1 - \beta_2^t)$ is mathematically necessary near $t=1$
  - `9.22.6` AdamW (Decoupled Weight Decay): Loshchilov & Hutter''s proof that $L_2$ regularization $\neq$ weight decay in adaptive optimizers; AdamW formulation
- **Key Failure Modes & Edge Cases**: Using standard Adam with $L_2$ penalty instead of AdamW, causing heavily updated weights to decay slower than rarely updated weights.
- **Verification & Mastery Check**: Implement SGD with Momentum, RMSprop, and AdamW from scratch in pure NumPy; compare convergence trajectories on a Rosenbrock function.
- **Project Application**: GradFlow & TransformerLab: Production AdamW optimizer engine.', '{"solution.py": "# Phase 9 // Lesson 9.22: Advanced Optimizers: Momentum, Nesterov, RMSprop & AdamW\n\ndef solve():\n    \"\"\"\n    Verification: Implement SGD with Momentum, RMSprop, and AdamW from scratch in pure NumPy; compare convergence traj\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.22", "subtopics_count": 6, "verification_criteria": "Implement SGD with Momentum, RMSprop, and AdamW from scratch in pure NumPy; compare convergence trajectories on a Rosenbrock function.", "subtopics": ["9.22.1 Momentum: exponential moving average of past gradients ($v_t = \\beta v_{t-1} + g_t$); dampening oscillations in ravines", "9.22.2 Nesterov Accelerated Gradient (NAG): computing gradient after looking ahead along current momentum vector", "9.22.3 RMSprop: adaptive learning rates dividing gradient by root-mean-square of running squared gradients ($s_t = \\beta s_{t-1} + (1-\\beta)g_t^2$)", "9.22.4 Adam (Adaptive Moment Estimation): combining 1st moment (momentum) and 2nd moment (RMSprop) with bias correction for initial steps", "9.22.5 Adam bias correction derivation: why dividing by $(1 - \\beta_1^t)$ and $(1 - \\beta_2^t)$ is mathematically necessary near $t=1$", "9.22.6 AdamW (Decoupled Weight Decay): Loshchilov & Hutter''s proof that $L_2$ regularization $\\neq$ weight decay in adaptive optimizers; AdamW formulation"]}'::jsonb, '["Explain how this implementation prevents: Using standard Adam with $L_2$ penalty instead of AdamW, causing heavily updated weights to decay slower than rarely upd", "How does Advanced Optimizers: Momentum, Nesterov, RMSprop & AdamW scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-23', 'phase-09-lesson-23-learning-rate-schedulers-regularization-t', 'module-4', 23, 'Lesson 4.23: Learning Rate Schedulers & Regularization Techniques', 'Prerequisites: Lesson 9.22', 'Prerequisites: Lesson 9.22 | Subtopics: 6 items', 'Systems project application', 280, 10, 2370.0, 1150.0, '# Lesson 9.23: Learning Rate Schedulers & Regularization Techniques

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.22
- **Subtopics**:
  - `9.23.1` Learning rate scheduling: Step decay, Exponential decay, and Cosine Annealing schedules
  - `9.23.2` Linear Warmup: starting with small learning rate to prevent early unstable gradients from destroying pre-trained or initialized weights
  - `9.23.3` Cosine Annealing with Warmup: modern standard schedule in LLM pre-training ($T_{warmup}$, $T_{max}$, $\eta_{min}$)
  - `9.23.4` $L_2$ Regularization (Ridge / Weight Decay): shrinking weights toward zero, geometric interpretation as constraining parameter norm ball
  - `9.23.5` $L_1$ Regularization (Lasso): sparsity induction, geometric interpretation at coordinate corners
  - `9.23.6` Dropout: randomly zeroing activations with probability $p$ during training; inverted dropout scaling ($\frac{1}{1-p}$) to preserve inference expectation
- **Key Failure Modes & Edge Cases**: Failing to scale inverted dropout by $\frac{1}{1-p}$ during training, causing activation magnitudes to diverge between train and eval modes.
- **Verification & Mastery Check**: Implement Cosine Annealing with Warmup scheduler and Inverted Dropout from scratch; verify learning rate schedule curves.
- **Project Application**: TransformerLab: Training loop scheduler and regularization.', '{"solution.py": "# Phase 9 // Lesson 9.23: Learning Rate Schedulers & Regularization Techniques\n\ndef solve():\n    \"\"\"\n    Verification: Implement Cosine Annealing with Warmup scheduler and Inverted Dropout from scratch; verify learning \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.23", "subtopics_count": 6, "verification_criteria": "Implement Cosine Annealing with Warmup scheduler and Inverted Dropout from scratch; verify learning rate schedule curves.", "subtopics": ["9.23.1 Learning rate scheduling: Step decay, Exponential decay, and Cosine Annealing schedules", "9.23.2 Linear Warmup: starting with small learning rate to prevent early unstable gradients from destroying pre-trained or initialized weights", "9.23.3 Cosine Annealing with Warmup: modern standard schedule in LLM pre-training ($T_{warmup}$, $T_{max}$, $\\eta_{min}$)", "9.23.4 $L_2$ Regularization (Ridge / Weight Decay): shrinking weights toward zero, geometric interpretation as constraining parameter norm ball", "9.23.5 $L_1$ Regularization (Lasso): sparsity induction, geometric interpretation at coordinate corners", "9.23.6 Dropout: randomly zeroing activations with probability $p$ during training; inverted dropout scaling ($\\frac{1}{1-p}$) to preserve inference expectation"]}'::jsonb, '["Explain how this implementation prevents: Failing to scale inverted dropout by $\\frac{1}{1-p}$ during training, causing activation magnitudes to diverge between t", "How does Learning Rate Schedulers & Regularization Techniques scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-24', 'phase-09-lesson-24-building-an-autograd-engine-i-the-value-n', 'module-4', 24, 'Lesson 4.24: Building an Autograd Engine I: The Value Node & Computational Graph', 'Prerequisites: Lesson 9.8, Lesson 9.17', 'Prerequisites: Lesson 9.8, Lesson 9.17 | Subtopics: 6 items', 'Systems project application', 280, 10, 2250.0, 1200.0, '# Lesson 9.24: Building an Autograd Engine I: The Value Node & Computational Graph

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.8, Lesson 9.17
- **Subtopics**:
  - `9.24.1` Architecture of an automatic differentiation engine: tracing operations during forward execution to build a dynamic computation graph
  - `9.24.2` The `Value` / `Node` scalar data structure: holding `data`, `grad`, `_prev` children set, `_op` label, and `_backward` closure
  - `9.24.3` Operator overloading in Python: implementing `__add__`, `__mul__`, `__sub__`, `__pow__`, `__neg__`, `__truediv__`
  - `9.24.4` Defining scalar backward closures: writing the local derivative chain rule directly inside overloaded operator methods
  - `9.24.5` The accumulation invariant: why gradients must accumulate (`grad += ...`) rather than assign (`grad = ...`) to support node reuse
  - `9.24.6` Graph visualization: rendering the computational DAG with Graphviz/dot to trace forward values and backward adjoints
- **Key Failure Modes & Edge Cases**: Overwriting gradients (`self.grad = out.grad * ...`) instead of accumulating (`self.grad += ...`), causing incorrect gradients on branching graphs.
- **Verification & Mastery Check**: Implement a micro-autograd scalar engine supporting addition, multiplication, powers, and ReLU with automatic backward execution.
- **Project Application**: GradFlow: Scalar autograd proof-of-concept.', '{"solution.py": "# Phase 9 // Lesson 9.24: Building an Autograd Engine I: The Value Node & Computational Graph\n\ndef solve():\n    \"\"\"\n    Verification: Implement a micro-autograd scalar engine supporting addition, multiplication, powers, and ReLU with \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.24", "subtopics_count": 6, "verification_criteria": "Implement a micro-autograd scalar engine supporting addition, multiplication, powers, and ReLU with automatic backward execution.", "subtopics": ["9.24.1 Architecture of an automatic differentiation engine: tracing operations during forward execution to build a dynamic computation graph", "9.24.2 The `Value` / `Node` scalar data structure: holding `data`, `grad`, `_prev` children set, `_op` label, and `_backward` closure", "9.24.3 Operator overloading in Python: implementing `__add__`, `__mul__`, `__sub__`, `__pow__`, `__neg__`, `__truediv__`", "9.24.4 Defining scalar backward closures: writing the local derivative chain rule directly inside overloaded operator methods", "9.24.5 The accumulation invariant: why gradients must accumulate (`grad += ...`) rather than assign (`grad = ...`) to support node reuse", "9.24.6 Graph visualization: rendering the computational DAG with Graphviz/dot to trace forward values and backward adjoints"]}'::jsonb, '["Explain how this implementation prevents: Overwriting gradients (`self.grad = out.grad * ...`) instead of accumulating (`self.grad += ...`), causing incorrect gra", "How does Building an Autograd Engine I: The Value Node & Computational Graph scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-9-25', 'phase-09-lesson-25-building-an-autograd-engine-ii-topologica', 'module-4', 25, 'Lesson 4.25: Building an Autograd Engine II: Topological Sort & Backward Engine', 'Prerequisites: Lesson 9.24', 'Prerequisites: Lesson 9.24 | Subtopics: 6 items', 'Systems project application', 280, 10, 2310.0, 1250.0, '# Lesson 9.25: Building an Autograd Engine II: Topological Sort & Backward Engine

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 9.24
- **Subtopics**:
  - `9.25.1` The dependency problem in reverse-mode AD: a node cannot execute its backward pass until all its parent nodes have propagated their gradients
  - `9.25.2` Directed Acyclic Graph (DAG) properties: topological ordering definition and guarantees
  - `9.25.3` Topological sort algorithms: Depth-First Search (DFS) post-order traversal with a visited set to build reversed evaluation order
  - `9.25.4` The `.backward()` function: setting root node adjoint to 1.0 (`self.grad = 1.0`), sorting graph topologically, and invoking `_backward()` in reverse
  - `9.25.5` Handling cycles: validating graph acyclicity; raising explicit exceptions on cyclic dependencies
  - `9.25.6` Edge cases: handling scalar constants, shared variables ($z = x + x$, $z = x \cdot x$), and multi-path branch reconvergence
- **Key Failure Modes & Edge Cases**: Invoking backward passes in arbitrary graph order rather than strict reverse topological sort, producing incomplete partial gradients.
- **Verification & Mastery Check**: Implement DFS topological sorting in the autograd engine; verify exact gradient calculation on diamond-shaped computational graphs ($x \to y, z \to w$).
- **Project Application**: GradFlow: Graph topological sorting and backward coordinator.', '{"solution.py": "# Phase 9 // Lesson 9.25: Building an Autograd Engine II: Topological Sort & Backward Engine\n\ndef solve():\n    \"\"\"\n    Verification: Implement DFS topological sorting in the autograd engine; verify exact gradient calculation on diamo\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "9.25", "subtopics_count": 6, "verification_criteria": "Implement DFS topological sorting in the autograd engine; verify exact gradient calculation on diamond-shaped computational graphs ($x \\to y, z \\to w$).", "subtopics": ["9.25.1 The dependency problem in reverse-mode AD: a node cannot execute its backward pass until all its parent nodes have propagated their gradients", "9.25.2 Directed Acyclic Graph (DAG) properties: topological ordering definition and guarantees", "9.25.3 Topological sort algorithms: Depth-First Search (DFS) post-order traversal with a visited set to build reversed evaluation order", "9.25.4 The `.backward()` function: setting root node adjoint to 1.0 (`self.grad = 1.0`), sorting graph topologically, and invoking `_backward()` in reverse", "9.25.5 Handling cycles: validating graph acyclicity; raising explicit exceptions on cyclic dependencies", "9.25.6 Edge cases: handling scalar constants, shared variables ($z = x + x$, $z = x \\cdot x$), and multi-path branch reconvergence"]}'::jsonb, '["Explain how this implementation prevents: Invoking backward passes in arbitrary graph order rather than strict reverse topological sort, producing incomplete part", "How does Building an Autograd Engine II: Topological Sort & Backward Engine scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb)
